    {
      "rank": 1,
      "ballot_id": "B011",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "A fundamental new classification of electronic matter, with a decisive experimental realization and enduring influence across condensed-matter physics.",
        "attribution": "Kane and Mele provided the quantum spin Hall/topological-insulator framework; Molenkamp led a landmark experimental realization.",
        "maturity": "The phenomenon has been repeatedly confirmed, broadly developed, and has had ample time to establish its physical importance.",
        "uncertainties": [
          "The wider topological-insulator story includes additional essential theoretical and experimental contributors."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B023",
      "proposed_laureates": [
        "Antoine Georges",
        "Dieter Vollhardt",
        "Gabriel Kotliar"
      ],
      "assessment": {
        "nobel_worthiness": "Dynamical mean-field theory made strongly correlated electronic materials quantitatively tractable and transformed their interpretation.",
        "attribution": "Vollhardt and collaborators established the method's foundations; Georges and Kotliar were central to its modern formulation and impact.",
        "maturity": "Its predictions and conceptual framework have been tested for decades against spectroscopy and materials behavior.",
        "uncertainties": [
          "Credit is distributed across a substantial theoretical community and depends on how narrowly the contribution is defined."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Jagadeesh S. Moodera",
        "Stuart S. P. Parkin",
        "Terunobu Miyazaki"
      ],
      "assessment": {
        "nobel_worthiness": "Room-temperature tunnel magnetoresistance, especially MgO-based junctions, is a clear physical discovery with major technological consequence.",
        "attribution": "Miyazaki and Moodera established large room-temperature TMR, while Parkin was pivotal in high-performance MgO junctions and translation.",
        "maturity": "The effect is robust, reproduced worldwide, and central to mature magnetic-memory technology.",
        "uncertainties": [
          "The evolution from early TMR to MgO giant TMR involves several closely connected priority claims."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B021",
      "proposed_laureates": [
        "Michael Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "Geometric and topological phases exposed a deep, experimentally consequential aspect of quantum mechanics with influence far beyond its original setting.",
        "attribution": "Aharonov is identified with the Aharonov-Bohm effect and Berry with the adiabatic geometric phase.",
        "maturity": "Both ideas have received extensive experimental confirmation and underpin much contemporary topological quantum physics.",
        "uncertainties": [
          "The two effects are historically and conceptually related but not a single narrowly bounded discovery."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Bart J. van Wees",
        "Henk van Houten",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Conductance quantization provided a striking direct manifestation of quantum transport in mesoscopic conductors and seeded a major field.",
        "attribution": "van Wees and van Houten were central to the original quantum-point-contact observations; Pepper's work was also foundational.",
        "maturity": "The result is exceptionally reproducible and its interpretation is firmly established.",
        "uncertainties": [
          "Independent near-simultaneous observations and device-development contributors complicate a three-person allocation."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "The quantum cascade laser created a new semiconductor-laser principle and a powerful infrared technology.",
        "attribution": "Capasso developed the central band-structure concept, Faist realized the device, and Cho enabled the heterostructure platform.",
        "maturity": "Three decades of development have demonstrated both the soundness of the physics and broad practical value.",
        "uncertainties": [
          "The appropriate division between conceptual invention, epitaxial enabling work, and experimental realization requires careful historical review."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Nicola A. Spaldin",
        "Ramamoorthy Ramesh",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Modern multiferroics revealed controllable coupling between electric and magnetic order, opening a distinctive materials-physics field.",
        "attribution": "Spaldin supplied influential design principles, while Ramesh and Tokura made decisive experimental and materials contributions.",
        "maturity": "The central phenomena are well established across many compounds, although device impact remains less mature.",
        "uncertainties": [
          "Multiferroicity has older roots and the field contains many important discovery pathways."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B039",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions established a vivid realization of topological spin textures and emergent electrodynamics in real materials.",
        "attribution": "Pfleiderer and Tokura led influential experimental discoveries in complementary chiral-magnet systems.",
        "maturity": "The observations are robust and the physics is now well developed, with continuing spintronic relevance.",
        "uncertainties": [
          "Theoretical originators and several experimental groups have substantial claims to credit."
        ]
      }
    }
  ]
}
